<!--vbase-->
<template>
  <div class="code-editor-wrapper">
    <div ref="aceContainer" class="code-editor-surface"></div>
  </div>
</template>

<script>
import { defineComponent } from 'vue';

import ace from 'ace-builds';
import 'ace-builds/src-noconflict/mode-xml';
import 'ace-builds/src-noconflict/mode-json';
import 'ace-builds/src-noconflict/mode-python';
import 'ace-builds/src-noconflict/ext-searchbox';
import 'ace-builds/src-noconflict/ext-language_tools';
import 'ace-builds/src-noconflict/theme-tomorrow_night_eighties';

import beautify from 'js-beautify';

export default defineComponent({
  props: {
    modelValue: {
      type: String,
      default: '',
    },
    language: {
      type: String,
      default: 'python',
    },
    readOnly: {
      type: Boolean,
      default: false,
    },
    formatCode: {
      type: Boolean,
      default: false,
    },
    placeholder: {
      type: String,
      default: '',
    },
    wrap: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['update:modelValue', 'formatComplete'],
  data() {
    return {
      editorInstance: null,
      isApplyingExternalChange: false,
    };
  },
  mounted() {
    this.initializeEditor();
    if (this.modelValue === '' && this.placeholder) {
      this.$emit('update:modelValue', this.placeholder);
    }
  },
  beforeUnmount() {
    if (this.editorInstance) {
      this.editorInstance.destroy();
      this.editorInstance = null;
    }
  },
  watch: {
    modelValue(newVal) {
      if (newVal === '' && this.placeholder) {
        this.$emit('update:modelValue', this.placeholder);
        return;
      }
      if (
        this.editorInstance &&
        this.editorInstance.getValue() !== newVal
      ) {
        this.applyExternalValue(newVal);
      }
    },
    formatCode(value) {
      if (value) {
        this.formatCodeScript();
      }
    },
    readOnly(value) {
      if (this.editorInstance) {
        this.editorInstance.setReadOnly(!!value);
      }
    },
    language(value) {
      if (this.editorInstance) {
        this.editorInstance.session.setMode(`ace/mode/${value}`);
      }
    },
    wrap(value) {
      if (this.editorInstance) {
        this.editorInstance.session.setUseWrapMode(!!value);
      }
    },
  },
  methods: {
    initializeEditor() {
      this.editorInstance = ace.edit(this.$refs.aceContainer, {
        mode: `ace/mode/${this.language}`,
        theme: 'ace/theme/tomorrow_night_eighties',
        value: this.modelValue || '',
        tabSize: 4,
        useSoftTabs: true,
        showPrintMargin: false,
        wrap: !!this.wrap,
        fontSize: '14px',
        readOnly: !!this.readOnly,
        enableBasicAutocompletion: true,
        enableLiveAutocompletion: true,
      });

      this.editorInstance.renderer.setScrollMargin(8, 8, 0, 0);

      this.editorInstance.session.on('change', () => {
        if (this.isApplyingExternalChange) return;
        const value = this.editorInstance.getValue();
        if (this.modelValue !== value) {
          this.$emit('update:modelValue', value);
        }
      });
    },
    applyExternalValue(value) {
      this.isApplyingExternalChange = true;
      this.editorInstance.setValue(value, -1);
      this.isApplyingExternalChange = false;
    },
    async formatCodeScript() {
      try {
        const formatted = await beautify(this.modelValue, {
          indent_size: 4,
          indent_char: ' ',
          preserve_newlines: true,
        });
        this.$emit('update:modelValue', formatted);
        if (this.editorInstance && this.editorInstance.getValue() !== formatted) {
          this.applyExternalValue(formatted);
        }
        this.$emit('formatComplete', false);
      } catch (err) {
        logError('Error formatting code:', err);
      }
    },
    focus() {
      this.editorInstance?.focus();
    },
    getEditor() {
      return this.editorInstance;
    },
  },
});
</script>

